export async function uploadBufferToS3(params: {
  buffer: Buffer;
  prefix: string;
  fileName: string;
  contentType: string;
}): Promise<string | null> {
  const extension = params.contentType.split("/")[1] ?? "png";
  const uniqueFileName = `${params.prefix}/${params.fileName}.${extension}`;

  const command = new PutObjectCommand({
    Bucket: getR2BucketName(),
    Key: uniqueFileName,
    Body: params.buffer,
    ContentType: params.contentType,
  });

  try {
    await s3.send(command);
    return `${getR2PublicUrl()}/${uniqueFileName}`;
  } catch (error) {
    logger.error("Failed to upload buffer to S3", error);
    return null;
  }
}

function getR2BucketName() {
  const bucket = process.env.R2_S3_BUCKET_NAME;
  if (!bucket) throw new Error("R2_S3_BUCKET_NAME is not configured");
  return bucket;
}

function getR2PublicUrl() {
  const url = process.env.R2_URL;
  if (!url) throw new Error("R2_URL is not configured");
  return url;
}

function getAnonymizedTextDescription(options: AnonymizationOptions) {
  if (!options.text) return undefined;
  return "Readable text replaced by numbered lorem placeholder text while preserving color, size, layout, and typography style.";
}

async function uploadBytes(params: {
  bytes: ArrayBuffer;
  contentType: string;
  prefix: string;
  fileName?: string;
}) {
  const url = await uploadBufferToS3({
    buffer: Buffer.from(params.bytes),
    prefix: params.prefix,
    fileName: params.fileName ?? `${Date.now()}`,
    contentType: params.contentType,
  });
  if (!url) throw new ActionError("Failed to upload image");
  return url;
}

async function downloadAndUploadImage(imageUrl: string, fallbackUrl?: string) {
  let response = await fetch(imageUrl);
  if (!response.ok && fallbackUrl) {
    response = await fetch(fallbackUrl);
  }
  if (!response.ok) {
    throw new ActionError("Failed to fetch YouTube thumbnail");
  }

  const contentType = response.headers.get("content-type") ?? "image/jpeg";
  return uploadBytes({
    bytes: await response.arrayBuffer(),
    contentType,
    prefix: "inspirations",
    fileName: `thumbnail-${Date.now()}`,
  });
}

