    imageUrls: v.array(v.string()),
    sourceUrl: v.optional(v.string()),
    sourceVideoTitle: v.optional(v.string()),
    sourceVideoAuthor: v.optional(v.string()),
    sourceVideoThumbnailUrl: v.optional(v.string()),
