                {!hasYoutubeUrl && !hasUploadedImages && (
                  <button
                    type="button"
                    onClick={() => {
                      onOpenChange(false);
                      setBulkImportOpen(true);
                    }}
                    className="text-muted-foreground hover:text-foreground text-xs transition-colors"
                  >
