            )}

            {previewImageUrl ? (
              <div className="grid gap-4 lg:grid-cols-[minmax(0,1fr)_16rem]">
                <div className="flex min-w-0 flex-col gap-3">
                  {renderPreview(previewImageUrl)}
                  {phase === "idle" && hasUploadedImages && !hasYoutubeUrl && (
                    <MultiImageUploader
