                    />
                  )}
                </div>
                {renderActionPanel()}
              </div>
            ) : phase === "idle" ? (
              <>
                {!hasYoutubeUrl && !hasUploadedImages && (
                  <div className="flex items-center gap-3">
                    <div className="bg-border h-px flex-1" />
                    <span className="text-muted-foreground text-xs font-medium uppercase">
                      or
                    </span>
