              placeholder="Search inspirations..."
              value={search}
              onChange={(event) => setSearch(event.target.value)}
              className="pl-9"
            />
          </div>
          <Tabs
            value={filter}
            onValueChange={(value) => updateFilter(value as InspirationFilter)}
          >
            <TabsList>
              <TabsTrigger value="mine">My Library</TabsTrigger>
              <TabsTrigger value="all">Community</TabsTrigger>
            </TabsList>
          </Tabs>
          <Select
            value={category ?? "all"}
            onValueChange={(value) =>
              setCategory(
                value === "all" ? undefined : (value as ThumbnailCategory),
              )
            }
          >
            <SelectTrigger className="w-[150px]">
              <SelectValue placeholder="Category" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="all">All Categories</SelectItem>
              {THUMBNAIL_CATEGORIES.map((thumbnailCategory) => (
                <SelectItem key={thumbnailCategory} value={thumbnailCategory}>
                  {thumbnailCategory}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>

        {isLoading ? (
          <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-3">
            {[1, 2, 3].map((item) => (
              <Skeleton key={item} className="aspect-video w-full rounded-2xl" />
            ))}
          </div>
        ) : inspirations.length === 0 ? (
          <EmptyState
            title="No inspirations yet"
            description="Add YouTube thumbnails as style references for your generations."
            action={
              <Button onClick={() => setDialogOpen(true)}>
                <Plus className="mr-2 size-4" />
                Add Inspiration
              </Button>
            }
          />
        ) : (
          <>
            <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-3">
              {inspirations.map((inspiration) => (
                <InspirationCard
                  key={inspiration.id}
                  inspiration={inspiration}
                  orgSlug={orgSlug}
                />
              ))}
            </div>
            <div ref={loadMoreRef} className="flex justify-center py-8">
              {isFetchingNextPage ? (
                <Loader2 className="text-muted-foreground size-6 animate-spin" />
              ) : hasNextPage ? (
                <Button variant="outline" onClick={() => void fetchNextPage()}>
                  Load more
                </Button>
              ) : null}
            </div>
          </>
        )}
      </LayoutContent>
    </Layout>
  );
}

function InspirationCard({
  inspiration,
  orgSlug,
}: {
  inspiration: InspirationListItem;
  orgSlug: string;
}) {
  const deleteInspiration = useConvexMutation(deleteInspirationRef);
  const detailsHref = `/orgs/${orgSlug}/inspirations/${inspiration.id}`;
  const hasImage = Boolean(inspiration.thumbnailUrls[0]);
  const relativeDate = formatDistanceToNow(new Date(inspiration.createdAt));

  const deleteMutation = useMutation({
    mutationFn: async () => {
      return deleteInspiration({ orgSlug, inspirationId: inspiration.id });
    },
    onSuccess: async () => {
      toast.success("Inspiration deleted");
    },
    onError: (error) => {
      toast.error(error.message);
    },
  });

  const handleDelete = () => {
    dialogManager.confirm({
      title: "Delete inspiration",
      description:
        "Are you sure you want to delete this inspiration? This action cannot be undone.",
      variant: "destructive",
      action: {
        label: "Delete",
        variant: "destructive",
        onClick: async () => {
          await deleteMutation.mutateAsync();
        },
      },
    });
  };

  return (
    <ContextMenu>
      <ContextMenuTrigger asChild>
        <div className="group relative aspect-video cursor-pointer overflow-hidden rounded-2xl border border-border transition-colors duration-150 hover:border-primary/50">
          {/* Full-bleed image */}
          <Link href={detailsHref} className="absolute inset-0 block">
            {hasImage ? (
              <Image
                src={inspiration.thumbnailUrls[0]}
                alt={inspiration.name}
                fill
                className="object-cover"
              />
            ) : (
              <div className="bg-muted flex size-full items-center justify-center">
                <ImageIcon className="text-muted-foreground size-10" />
              </div>
            )}
          </Link>

          {/* Gradient scrim — only over bottom half for text legibility */}
          {hasImage ? (
            <div
              className="pointer-events-none absolute inset-0"
              style={{
                background:
                  "linear-gradient(to top, oklch(0.10 0 0 / 0.82) 0%, transparent 50%)",
              }}
            />
          ) : null}

          {/* Three-dot menu — near-invisible at rest, revealed on hover */}
          <div className="absolute top-2 right-2 z-20 opacity-35 transition-opacity duration-150 group-hover:opacity-100">
            <DropdownMenu>
              <DropdownMenuTrigger asChild>
                <Button
                  variant="ghost"
                  size="icon"
                  className="size-7 rounded-md hover:bg-black/50"
                  onClick={(event) => {
                    event.preventDefault();
                    event.stopPropagation();
                  }}
                >
                  <MoreVertical className="size-3.5 text-white" />
                </Button>
              </DropdownMenuTrigger>
              <DropdownMenuContent align="end">
                <DropdownMenuItem asChild>
                  <Link href={detailsHref}>
                    <ExternalLink className="mr-2 size-4" />
                    View Details
                  </Link>
                </DropdownMenuItem>
                {inspiration.hasDrawing ? (
                  <DropdownMenuItem asChild>
                    <Link
                      href={`/orgs/${orgSlug}/inspirations/draw?inspirationId=${inspiration.id}`}
                    >
                      <Pencil className="mr-2 size-4" />
                      Edit drawing
                    </Link>
                  </DropdownMenuItem>
                ) : null}
                {inspiration.youtubeUrl ? (
                  <DropdownMenuItem asChild>
                    <a
                      href={inspiration.youtubeUrl}
                      target="_blank"
                      rel="noopener noreferrer"
                    >
                      <ExternalLink className="mr-2 size-4" />
                      Open YouTube
                    </a>
                  </DropdownMenuItem>
                ) : null}
                <DropdownMenuItem
                  onClick={handleDelete}
                  className="text-destructive focus:text-destructive"
                >
                  <Trash2 className="mr-2 size-4" />
                  Delete
                </DropdownMenuItem>
              </DropdownMenuContent>
            </DropdownMenu>
          </div>

          {/* Bottom info — title and relative date, subtle overlay */}
          {hasImage ? (
            <Link
              href={detailsHref}
              className="absolute inset-x-0 bottom-0 z-10 block p-3"
            >
              <Typography
                variant="small"
                as="h3"
                className="line-clamp-1 text-white/75"
              >
                {inspiration.name}
              </Typography>
              <Typography
                variant="muted"
                as="p"
                className="mt-0.5 text-[10.5px] text-white/30"
              >
                {relativeDate} ago
              </Typography>
            </Link>
          ) : null}
        </div>
      </ContextMenuTrigger>

      <ContextMenuContent>
        <ContextMenuItem asChild>
          <Link href={detailsHref}>
            <ExternalLink className="mr-2 size-4" />
            View Details
          </Link>
        </ContextMenuItem>
        {inspiration.hasDrawing ? (
          <ContextMenuItem asChild>
            <Link
              href={`/orgs/${orgSlug}/inspirations/draw?inspirationId=${inspiration.id}`}
            >
              <Pencil className="mr-2 size-4" />
              Edit drawing
            </Link>
          </ContextMenuItem>
        ) : null}
        {inspiration.youtubeUrl ? (
          <ContextMenuItem asChild>
            <a
              href={inspiration.youtubeUrl}
              target="_blank"
              rel="noopener noreferrer"
            >
              <ExternalLink className="mr-2 size-4" />
              Open YouTube
            </a>
          </ContextMenuItem>
        ) : null}
        <ContextMenuItem
          onClick={handleDelete}
          className="text-destructive focus:text-destructive"
        >
          <Trash2 className="mr-2 size-4" />
          Delete
        </ContextMenuItem>
      </ContextMenuContent>
    </ContextMenu>
  );
}

