            >
              <rect width={DRAWING_WIDTH} height={DRAWING_HEIGHT} fill="#fffef9" />
              {document.objects.map((object) => (
                <SceneObject
                  key={object.id}
                  object={object}
                  editing={editingText?.id === object.id}
