  },
  {
    id: "kn7bc60pcpc82y2s47txats6rs87894z",
    legacyId: "hda__HgCuIB",
  },
] as const;
const ACTIVE_SUBSCRIPTION_STATUSES = new Set([
  "active",
  "trialing",
  "lifetime",
]);
const YOUTUBE_HOSTS = new Set([
  "youtube.com",
  "www.youtube.com",
  "m.youtube.com",
]);
const YOUTUBE_IMAGE_HOSTS = new Set(["i.ytimg.com", "img.youtube.com"]);

type AppCtx = {
  db: any;
  runQuery: (fn: any, args: any) => Promise<any>;
  runMutation?: (fn: any, args: any) => Promise<any>;
};

type StoredImage = {
  url: string;
  key?: string;
  width?: number;
  height?: number;
  contentType?: string;
};

type InspirationRow = {
  _id: string;
  organizationId: string;
  title: string;
  description?: string;
  sourceUrl?: string;
  sourceVideoTitle?: string;
  sourceVideoAuthor?: string;
  sourceVideoThumbnailUrl?: string;
  image?: StoredImage;
  images?: StoredImage[];
  categories?: string[];
  hasPlaceholder?: boolean;
  anonymizedSubject?: boolean;
  anonymizedText?: boolean;
  anonymizedLogos?: boolean;
  anonymizedTextDescription?: string;
  drawing?: string;
  isPublic?: boolean;
  adminReview?: string;
  reviewedAt?: number;
  deletedAt?: number;
  createdAt: number;
  updatedAt: number;
};

const createFromUploadedUrlsRef = makeFunctionReference<
  "mutation",
  {
    orgSlug: string;
    imageUrls: string[];
    sourceUrl?: string;
    sourceVideoTitle?: string;
    sourceVideoAuthor?: string;
    sourceVideoThumbnailUrl?: string;
    title: string;
    description: string;
